CREATE OR REPLACE FUNCTION efg_private.coach119_guard_flexible_guide_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_old_kind text:=null;
begin
 if tg_op='UPDATE' then v_old_kind:=old.guided_plan->>'kind'; end if;
 if (new.guided_plan->>'kind'='flexible_meal_guide'
    or v_old_kind='flexible_meal_guide')
   and efg_private.coach119_is_atomic_transaction() is distinct from true then
  raise exception 'Flexible Coach guides require signed atomic publication'
   using errcode='42501';
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION efg_private.coach_diary_write_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_enabled boolean := false;
 v_role text;
 v_actor uuid;
 v_status jsonb;
begin
 select enabled into v_enabled
 from efg_private.coach_release_switches
 where switch_key='pilot_student_diary_write_gate';
 -- OFF: preserve legacy PWA diary writes byte-for-byte.
 if v_enabled is distinct from true then return new; end if;

 -- Authenticated service maintenance is independent from the student's UI.
 v_role := auth.role();
 if v_role='service_role' then return new; end if;

 v_actor := auth.uid();
 if v_actor is null or new.student_id is distinct from v_actor then
  raise exception 'Only the signed student may write this diary after pilot release'
   using errcode='42501';
 end if;
 if tg_op='UPDATE' and new.student_id is distinct from old.student_id then
  raise exception 'Diary owner cannot change' using errcode='42501';
 end if;

 -- COACH116 legal-first status reads current signed coach/org, two legal
 -- versions, two pilot consents, shared general intake and published goal+guide.
 -- No browser-provided eligibility value can bypass this check.
 v_status:=public.efg_coach_pilot_entry_status();
 if pg_catalog.jsonb_typeof(v_status) is distinct from 'object' or
    v_status->>'route' is distinct from 'ready' or
    v_status->>'can_log_meals' is distinct from 'true' then
  raise exception 'Tu coach todavía debe publicar tu objetivo y guía antes de registrar comidas'
    using errcode='42501';
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION efg_private.coach_guide_foods_verified(p_guide jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
 v_meal jsonb;
 v_item jsonb;
 v_food efg_private.coach_reviewed_foods%rowtype;
 v_food_id text;
 v_units text;
 v_value numeric;
 v_key text;
 v_source numeric;
 v_slots text[] := '{}';
 v_items_count integer;
 v_count integer := 0;
begin
 if pg_catalog.jsonb_typeof(p_guide) is distinct from 'object'
  or pg_catalog.jsonb_typeof(p_guide->'meals') is distinct from 'array'
  or not (
   (p_guide->>'kind'='five_meal_example' and p_guide->>'version'='1'
    and pg_catalog.jsonb_array_length(p_guide->'meals')=5)
   or
   (p_guide->>'kind'='flexible_meal_guide' and p_guide->>'version'='2'
    and pg_catalog.jsonb_array_length(p_guide->'meals') between 2 and 6)
  ) then
   return false;
 end if;
 for v_meal in select value from pg_catalog.jsonb_array_elements(p_guide->'meals') loop
  if pg_catalog.jsonb_typeof(v_meal) is distinct from 'object'
   or v_meal->>'slot' is null or v_meal->>'slot' not in
    ('desayuno','media_manana','almuerzo','media_tarde','merienda','cena')
   or v_meal->>'slot'=any(v_slots)
   or pg_catalog.jsonb_typeof(v_meal->'items') is distinct from 'array' then
   return false;
  end if;
  v_slots:=pg_catalog.array_append(v_slots,v_meal->>'slot');
  v_items_count:=pg_catalog.jsonb_array_length(v_meal->'items');
  if v_items_count not between 1 and 15 then return false; end if;
  for v_item in select value from pg_catalog.jsonb_array_elements(v_meal->'items') loop
   v_count:=v_count+1;
   if v_count>90 or pg_catalog.jsonb_typeof(v_item) is distinct from 'object'
    or v_item->>'id' is null or v_item->>'unit' is null
    or v_item->>'id' !~ '^[a-zA-Z0-9_-]{1,100}$'
    or v_item->>'unit' not in ('g','ml')
    or pg_catalog.jsonb_typeof(v_item->'qty') is distinct from 'number' then
     return false;
   end if;
   if (v_item->>'qty')::numeric<=0 or (v_item->>'qty')::numeric>1000 then
    return false;
   end if;
   v_food_id:=v_item->>'id';
   v_units:=v_item->>'unit';
   select * into v_food from efg_private.coach_reviewed_foods
    where food_id=v_food_id and unit=v_units
      and evidence_status='reviewed'
      and reviewed_by is not null and reviewed_at is not null
      and expires_at>pg_catalog.now() and reviewed_at<=pg_catalog.now();
   if not found then return false; end if;
   foreach v_key in array array['k','p','c','f','fi'] loop
    if pg_catalog.jsonb_typeof(v_item->v_key) is distinct from 'number' then
     return false;
    end if;
    v_value:=(v_item->>v_key)::numeric;
    v_source:=(case v_key
      when 'k' then v_food.k when 'p' then v_food.p
      when 'c' then v_food.c when 'f' then v_food.f else v_food.fi end);
    if v_value<0 or abs(v_value-v_source) >
      (case when v_key='k' then 0.01 else 0.003 end) then
     return false;
    end if;
   end loop;
  end loop;
 end loop;
 return pg_catalog.cardinality(v_slots)=pg_catalog.jsonb_array_length(p_guide->'meals')
    and v_count>=pg_catalog.jsonb_array_length(p_guide->'meals');
end
$function$
